function lessonPhoto(key){const p=lessonPhotos[key];return `<figure class="source-photo"><img src="${p.file}" alt="${p.alt}" width="${p.width}" height="${p.height}" loading="lazy" decoding="async"><figcaption><strong>${p.title}</strong><p>${p.caption}</p><span class="photo-credit">${p.credit} · <a href="${p.source}" target="_blank" rel="noopener noreferrer">Original und Bildquelle</a> · <a href="${p.licenseUrl}" target="_blank" rel="license noopener noreferrer">${p.license}</a>${p.edits?` · ${p.edits}`:''}</span></figcaption></figure>`;}
/* Lesetexte und zugängliche Schaubilder für den direkten Systemvergleich. */
function lessonFigure(kind){
const figures={
plan:`<figure class="lesson-figure"><div class="figure-heading"><span>01</span><h3>So läuft die zentrale Planung</h3></div><div class="plan-map"><div class="map-node map-authority"><strong>Planungsbehörde</strong><span>stimmt Ziele, Mengen und den Einsatz von Mitteln ab</span></div><div class="map-channel"><span>↑ Informationen über Kapazitäten und Bedarf</span><span>↓ Produktionsvorgaben, Preise und Kontrolle</span></div><div class="map-pair"><div class="map-node"><strong>Unternehmen</strong><span>stellen Güter her</span></div><div class="map-node"><strong>Haushalte</strong><span>arbeiten und konsumieren</span></div></div><div class="map-exchange"><span>Unternehmen → Haushalte: Konsumgüter</span><span>Haushalte → Unternehmen: Arbeitsleistung</span></div></div><figcaption>Informationen laufen zur Zentrale; verbindliche Vorgaben laufen zurück. Das vereinfachte Schaubild zeigt Leistungen und Informationen, keine vollständigen Geldströme.</figcaption></figure>`,
anreize:`<figure class="lesson-figure"><div class="figure-heading"><span>02</span><h3>Die Kennzahl verändert das Verhalten</h3></div><div class="incentive-columns"><div><h4>Vorgabe: Stückzahl</h4><ol class="effect-chain"><li>Viele Schrauben werden belohnt.</li><li>Viele kleine Schrauben erleichtern die Zielerfüllung.</li><li>Die benötigten Größen können fehlen.</li></ol></div><div><h4>Vorgabe: Gewicht</h4><ol class="effect-chain"><li>Viele Kilogramm werden belohnt.</li><li>Große, schwere Schrauben erleichtern die Zielerfüllung.</li><li>Materialverbrauch und Bedarf können aus dem Blick geraten.</li></ol></div></div><p class="figure-takeaway">Die Kennzahl wird erfüllt. Der Bedarf möglicherweise nicht.</p><figcaption>Ein Gedankenbeispiel für Fehlanreize: Entscheidend ist, welche Leistung eine Regel belohnt. Nicht jeder Betrieb muss sich so verhalten.</figcaption></figure>`,
markt:`<figure class="lesson-figure"><div class="figure-heading"><span>03</span><h3>Wie ein Preis Entscheidungen verbindet</h3></div><ol class="signal-chain"><li><strong>Ein Gut wird knapper</strong><span>Zum Beispiel fällt ein Teil der Ernte aus.</span></li><li><strong>Der Preis kann steigen</strong><span>Mehr Kaufwünsche treffen auf weniger Angebot.</span></li><li><strong>Beide Seiten reagieren</strong><span>Anbieter prüfen zusätzliche Produktion. Manche Käufer verzichten oder weichen aus.</span></li></ol><figcaption>Die Reaktionen benötigen Zeit und hängen von Möglichkeiten und Zahlungsbereitschaft ab. Ein Preissignal ist kein Produktionsbefehl.</figcaption></figure>`,
price:`<figure class="lesson-figure"><div class="figure-heading"><span>04</span><h3>Ein Marktgleichgewicht im Schaubild</h3></div><svg class="market-plot" viewBox="0 0 600 380" role="img" aria-labelledby="price-chart-title price-chart-desc"><title id="price-chart-title">Schematische Angebots- und Nachfragekurve</title><desc id="price-chart-desc">Die Angebotskurve steigt, die Nachfragekurve fällt. Am Schnittpunkt stimmen angebotene und nachgefragte Menge überein. Bei einem Preis oberhalb des Schnittpunkts entsteht im dargestellten Modell ein Angebotsüberschuss; unterhalb ein Nachfrageüberschuss.</desc><defs><marker id="axis-arrow" markerWidth="6" markerHeight="6" refX="5" refY="3" orient="auto"><path d="M0 0L6 3L0 6Z" fill="currentColor"/></marker></defs><path class="plot-axis" d="M70 310V35M70 310H550" marker-end="url(#axis-arrow)"/><path class="plot-guide" d="M70 177.5H305V310"/><path class="plot-supply" d="M120 285L490 70"/><path class="plot-demand" d="M120 70L490 285"/><circle class="plot-point" cx="305" cy="177.5" r="8"/><text x="80" y="28">Preis</text><text x="470" y="352">Menge</text><text x="382" y="68" class="plot-supply-label">Angebot</text><text x="382" y="304" class="plot-demand-label">Nachfrage</text><text x="328" y="173">Gleichgewicht</text><text x="16" y="188">P*</text><text x="294" y="340">M*</text></svg><figcaption>Ein schematisches Modell: Am Schnittpunkt liegen Gleichgewichtspreis P* und Gleichgewichtsmenge M*. Die Linien zeigen keine gemessenen Daten. Die konkreten Mengen der Spargelaufgabe untersuchst du anschließend selbst.</figcaption></figure>`,
grenzen:`<figure class="lesson-figure"><div class="figure-heading"><span>05</span><h3>Zwei Fragen an jedes Wirtschaftssystem</h3></div><div class="lens-pair"><div><h4>Wie gut werden Mittel eingesetzt?</h4><p>Was wird mit Arbeit, Maschinen und Rohstoffen hergestellt?</p><strong>Frage nach Effizienz</strong></div><div><h4>Wer erhält die Ergebnisse?</h4><p>Wer kann die produzierten Güter nutzen oder bezahlen?</p><strong>Frage nach Verteilung</strong></div></div><p class="figure-takeaway">Hohe Effizienz entscheidet noch nicht darüber, ob eine Verteilung als gerecht gilt.</p><figcaption>Beide Fragen lassen sich an Plan- und Marktwirtschaft stellen. Auch eine politisch angestrebte gerechte Verteilung garantiert keine effiziente Produktion.</figcaption></figure>`,
vergleich:`<figure class="lesson-figure"><div class="figure-heading"><span>06</span><h3>Mehr Fahrräder werden gebraucht</h3></div><div class="comparison-routes"><section><h4>Zentralverwaltungswirtschaft</h4><ol class="effect-chain"><li>Die Behörde erhält Informationen über den Bedarf.</li><li>Sie ändert Pläne und teilt Produktionsmittel zu.</li><li>Betriebe erfüllen die neuen Vorgaben.</li></ol></section><section><h4>Freie Marktwirtschaft</h4><ol class="effect-chain"><li>Zusätzliche zahlungsfähige Nachfrage zeigt sich am Markt.</li><li>Preise und erwartete Gewinne können steigen.</li><li>Unternehmen entscheiden über mehr Produktion.</li></ol></section></div><figcaption>Dasselbe Versorgungsproblem, unterschiedliche Entscheidungswege. In beiden Fällen braucht zusätzliche Produktion Zeit und verfügbare Mittel.</figcaption></figure>`};return figures[kind];}
function applyReadingContent(){
stations[0].reading=`<div class="reading-article"><p class="reading-lead">Eine Wirtschaft muss ständig Entscheidungen treffen: Wie viele Wohnungen sollen entstehen? Welche Lebensmittel werden produziert? Wie viel Arbeit und Material stehen dafür zur Verfügung? Die Zentralverwaltungswirtschaft beantwortet diese Fragen vor allem durch verbindliche staatliche Planung.</p>${lessonPhoto('plan')}<h2>Ein Plan für viele einzelne Betriebe</h2><p>Im Grundmodell legt eine zentrale Planungsbehörde fest, <strong>was, wie und für wen produziert werden soll</strong>. Sie bestimmt Produktionsziele und stimmt den Einsatz knapper Mittel ab. Ein Fahrradbetrieb kann deshalb nicht einfach nur das herstellen, was ihm den höchsten Gewinn verspricht. Er erhält Vorgaben, beispielsweise zu Stückzahlen, Materialien und Lieferterminen. Seine Entscheidungen müssen sich innerhalb dieses Plans bewegen.</p><p>Dafür braucht die Behörde Informationen. Betriebe melden etwa, welche Maschinen, Beschäftigten und Vorräte sie haben. Staatliche Stellen sammeln Angaben über den Bedarf der Bevölkerung. Aus diesen Meldungen entstehen Pläne, die aufeinander abgestimmt werden müssen: Eine höhere Fahrradproduktion benötigt zum Beispiel zusätzlich Stahl, Reifen und Arbeitszeit. Diese Mittel fehlen dann möglicherweise an anderer Stelle.</p>${lessonFigure('plan')}<h2>Eigentum, Preise und Verteilung</h2><p>Produktionsmittel wie Fabriken, Maschinen oder große landwirtschaftliche Flächen befinden sich überwiegend in staatlichem oder genossenschaftlichem Eigentum. Damit kann die politische Planung ihren Einsatz maßgeblich bestimmen. <strong>Produktionsmittel sind vom persönlichen Eigentum zu unterscheiden.</strong> Kleidung, Möbel oder ein privat genutztes Fahrrad gehören zu einer anderen Kategorie. Genossenschaftliches Eigentum bedeutet außerdem nicht, dass der Staat der Eigentümer ist oder jede Person beliebig darüber verfügen darf.</p><p>Auch Preise und Löhne werden weitgehend staatlich festgelegt. Ein politisch niedrig gehaltener Preis kann ein wichtiges Gut zunächst erschwinglicher machen. Er sorgt aber allein noch nicht dafür, dass genügend davon produziert wird. Übersteigen die Kaufwünsche die verfügbare Menge, können Wartezeiten, Wartelisten oder andere Formen der Zuteilung entstehen. Ist der Preis im Verhältnis zu den Kaufwünschen hoch, können Güter unverkauft bleiben.</p><h2>Politisches Ziel und tatsächliches Ergebnis</h2><p>Eine zentrale Planung kann die Grundversorgung, hohe Beschäftigung oder bestimmte Investitionen zum Ziel haben. Ob sie diese Ziele erreicht, hängt von den verfügbaren Mitteln und der Qualität der Planung ab. Wirtschaftliche Verträge sind an die Vorgaben gebunden; die Vertragsfreiheit der Betriebe ist stark eingeschränkt. Der Staat übernimmt damit eine zentrale Entscheidungs- und Kontrollfunktion.</p><div class="model-note"><strong>Modell und Geschichte:</strong> Die DDR war überwiegend zentral geplant, hatte aber unterschiedliche Eigentumsformen und auch private Betriebe. Marx und Engels waren Vordenker des Sozialismus; sie entwarfen nicht die konkrete spätere DDR-Wirtschaftsordnung. Ein Modell vereinfacht diese historische Wirklichkeit.</div><p class="reading-question"><strong>Denke beim Lesen mit:</strong> Welche Informationen braucht eine Planungsbehörde, wenn im nächsten Jahr deutlich mehr Fahrräder hergestellt werden sollen?</p></div>`;
stations[1].reading=`<div class="reading-article"><p class="reading-lead">Ein zentraler Plan kann eine klare Richtung vorgeben. Seine größte Herausforderung besteht darin, die Möglichkeiten vieler Betriebe und die Wünsche vieler Menschen sinnvoll aufeinander abzustimmen. Dabei spielen Informationen und Anreize eine entscheidende Rolle.</p><h2>Was eine zentrale Planung leisten soll</h2><p>Eine mögliche Stärke liegt darin, <strong>Ressourcen für gemeinsame Aufgaben zu bündeln</strong>. Die politische Führung kann zum Beispiel Wohnungsbau oder die Versorgung mit Grundnahrungsmitteln zur Priorität machen. Auch die Sicherung von Beschäftigung oder eine gleichmäßigere Versorgung verschiedener Regionen kann ein politisches Ziel sein. Betriebe müssen dann nicht jede einzelne Entscheidung allein daran ausrichten, ob ein Vorhaben für sie gewinnbringend ist.</p><p>Diese Ziele können miteinander in Konflikt geraten. Wer sehr viel Material und Arbeitskraft für Wohnungen einsetzt, hat weniger davon für andere Güter. Eine gleichmäßigere Versorgung ist außerdem nicht automatisch eine gute Versorgung aller. <strong>Ein erwünschter Vorteil ist deshalb von einem tatsächlich erreichten Ergebnis zu unterscheiden.</strong> Aussagen wie „Planwirtschaft garantiert Vollbeschäftigung und bedarfsgerechte Produktion“ gehen zu weit.</p><h2>Warum gute Informationen schwierig sind</h2><p>Die Behörde müsste wissen, was Menschen benötigen, was sie sich wünschen und was Betriebe herstellen können. Doch Wünsche verändern sich, Lieferungen fallen aus und Produktionsverfahren entwickeln sich weiter. Informationen können unvollständig, veraltet oder schwer vergleichbar sein. Selbst ehrliche Meldungen ergeben deshalb nicht automatisch einen passenden Gesamtplan.</p><p>Hinzu kommen die Interessen der Beteiligten. Wenn ein Betrieb erwartet, dass eine hohe gemeldete Leistungsfähigkeit künftig zu besonders anspruchsvollen Vorgaben führt, kann er seine Möglichkeiten vorsichtig darstellen. Das ist ein möglicher Fehlanreiz. Die Behörde plant dann auf einer Grundlage, die nicht alle tatsächlich verfügbaren Möglichkeiten abbildet.</p>${lessonFigure('anreize')}<h2>Es gibt Anreize, aber wofür?</h2><p>Auch in der DDR gab es betriebliche Gewinne und Leistungsprämien. Die pauschale Aussage, niemand habe einen Anreiz zu guter Arbeit gehabt, ist falsch. Entscheidend ist vielmehr, <strong>woran Erfolg gemessen und eine Belohnung geknüpft wird</strong>. Eine Stückzahlvorgabe kann erfüllt sein, obwohl die Qualität nicht stimmt oder die hergestellten Größen nicht gebraucht werden. Eine Gewichtsvorgabe kann wiederum unnötigen Materialverbrauch begünstigen.</p><p>Wenn Vorgaben schlecht zum Bedarf passen, können gleichzeitig Mangel und Überschüsse entstehen: Von einem Produkt ist zu wenig vorhanden, von einem anderen zu viel. Auch neue Ideen können sich langsamer durchsetzen, wenn ein Betrieb dafür erst geänderte Vorgaben oder zusätzliche Mittel benötigt. Das bedeutet nicht, dass Innovation unmöglich ist. Es erklärt, warum die Regeln ihrer Umsetzung im Weg stehen können.</p><p class="reading-question"><strong>Denke beim Lesen mit:</strong> Wie müsste eine Vorgabe für Schrauben aussehen, damit nicht nur eine gute Kennzahl, sondern auch ein brauchbares Produkt entsteht?</p></div>`;
stations[2].reading=`<div class="reading-article"><p class="reading-lead">In einer freien Marktwirtschaft gibt es keinen zentralen Gesamtplan für alle Unternehmen. Trotzdem entstehen täglich viele Güter und Dienstleistungen. Die Abstimmung erfolgt über dezentrale Entscheidungen, Märkte und Preise.</p>${lessonPhoto('market')}<h2>Die zwei Säulen: Eigeninteresse und Preismechanismus</h2><p>Unternehmen entscheiden selbst, welche Güter sie anbieten und wie sie diese herstellen. Sie orientieren sich dabei unter anderem an ihren Kosten und den erwarteten Erlösen. Haushalte entscheiden, was sie kaufen und wofür sie ihr begrenztes Einkommen verwenden. Produktionsmittel befinden sich überwiegend in Privateigentum. Die Beteiligten verfolgen eigene Ziele: Unternehmen streben Gewinne an, Haushalte möchten ihre Bedürfnisse im Rahmen ihrer Möglichkeiten befriedigen.</p><p>Dieses <strong>Eigeninteresse</strong> erklärt den Antrieb wirtschaftlichen Handelns. Der <strong>Preismechanismus</strong> erklärt, wie die vielen Entscheidungen aufeinander bezogen werden. Ein Preis ist für Käufer eine Ausgabe und für Verkäufer ein möglicher Erlös. Verändert er sich, können beide Seiten ihre Entscheidungen überprüfen. Nicht alle müssen dabei die genaue Ursache der Veränderung kennen.</p>${lessonFigure('markt')}<h2>Was Angebot und Nachfrage aussagen</h2><p>Die angebotene Menge bezeichnet, wie viel Verkäufer zu einem bestimmten Preis verkaufen wollen. Die nachgefragte Menge bezeichnet, wie viel Käufer zu diesem Preis erwerben wollen und bezahlen können. Ein Wunsch allein ist daher noch keine Marktnachfrage. <strong>Zahlungsbereitschaft und Kaufkraft</strong> entscheiden mit darüber, welche Bedürfnisse sich am Markt bemerkbar machen.</p><p>Bei einem Preis, zu dem mehr nachgefragt als angeboten wird, liegt ein Nachfrageüberschuss vor. Das kann steigende Preise begünstigen. Höhere Preise können zusätzliche Anbieter anziehen; gleichzeitig verzichten manche Käufer auf den Kauf. Bei einem Angebotsüberschuss ist die angebotene Menge größer als die nachgefragte. Dann kann ein Anreiz entstehen, Preise zu senken. Diese Anpassungen sind Möglichkeiten, keine automatische Sofortreaktion aller Beteiligten.</p>${lessonFigure('price')}<h2>Gleichgewicht, Freiheit und Grenzen</h2><p>Im Marktgleichgewicht stimmen angebotene und nachgefragte Menge überein. Das heißt nicht, dass alle Wünsche erfüllt sind: Wer den Preis nicht bezahlen kann oder will, gehört bei diesem Preis nicht zur nachgefragten Menge. Auch sagt das Gleichgewicht allein nichts darüber aus, ob die Verteilung gerecht ist.</p><p>Grundsätzlich gilt Vertragsfreiheit innerhalb eines Rechtsrahmens. Löhne entstehen im Modell durch Angebot und Nachfrage auf Arbeitsmärkten sowie Vereinbarungen. Der Staat sichert im liberalen Grundmodell insbesondere Eigentum, Verträge und äußere Sicherheit. Auch dieses Modell kommt also nicht ohne staatliche Regeln aus.</p><div class="model-note"><strong>Vordenker und Wirklichkeit:</strong> Der schottische Ökonom Adam Smith ist ein wichtiger Vordenker der klassischen Ökonomie. Eigeninteresse trägt unter geeigneten Bedingungen zum Wohlstand bei; ein Nutzen für alle ist damit nicht garantiert. Die USA sind marktwirtschaftlich geprägt, haben jedoch zahlreiche staatliche Eingriffe und entsprechen keinem reinen Modell.</div><p class="reading-question"><strong>Denke beim Lesen mit:</strong> Warum kann ein steigender Spargelpreis für einen zusätzlichen Anbieter ein Anreiz sein, während ein bisheriger Käufer auf Spargel verzichtet?</p></div>`;
stations[3].reading=`<div class="reading-article"><p class="reading-lead">Dezentrale Entscheidungen können viel Wissen und viele Ideen nutzbar machen. Wettbewerb schafft dabei Chancen und setzt Unternehmen unter Druck. Ob die Ergebnisse zugleich effizient und gerecht sind, muss jedoch getrennt untersucht werden.</p><h2>Wie Wettbewerb wirken kann</h2><p>Wenn mehrere Unternehmen um Kunden konkurrieren, können sich gute Qualität, günstige Preise und neue Produkte lohnen. Ein Betrieb, der mit weniger Material dieselbe Leistung erreicht, kann seine Kosten senken. Ein Unternehmen, das einen bislang übersehenen Wunsch erfüllt, kann neue Kunden gewinnen. <strong>Gewinnchancen und Verlustrisiken</strong> schaffen deshalb Anreize für Innovation und wirtschaftliches Handeln.</p><p>Haushalte haben Wahlmöglichkeiten und Unternehmen können unterschiedliche Ideen ausprobieren. Entscheidungen müssen nicht erst in einen Gesamtplan aufgenommen werden. Das kann die Anpassung an neue Wünsche erleichtern. Allerdings sind weder Erfolg noch Wettbewerb dauerhaft garantiert. Wird ein Unternehmen sehr mächtig oder ist der Markteintritt für andere schwierig, kann der Wettbewerbsdruck abnehmen.</p>${lessonFigure('grenzen')}<h2>Was im Preis fehlen kann</h2><p>Ein Marktpreis berücksichtigt nicht notwendigerweise alle Folgen einer Handlung. Verursacht eine Produktion Schäden bei unbeteiligten Dritten, ohne dass diese Kosten vollständig in den Entscheidungen und Preisen berücksichtigt werden, liegt ein <strong>negativer externer Effekt</strong> vor. Aus Sicht des Unternehmens kann die Produktion lohnend sein, obwohl andere Menschen einen Teil der Kosten tragen. Das Eigeninteresse der Beteiligten führt dann nicht automatisch zu einem guten Ergebnis für die Gemeinschaft.</p><p>Ein weiteres Problem betrifft reine öffentliche Güter. Von ihrer Nutzung lassen sich Menschen kaum ausschließen; zugleich verringert die Nutzung durch eine Person die Nutzungsmöglichkeiten anderer nicht. Ein Beispiel ist der Schutz durch einen Deich innerhalb des geschützten Gebiets. Wenn Menschen auch ohne eigenen Beitrag profitieren, können freiwillige Zahlungen zur Finanzierung zu gering ausfallen.</p><p>Bildung oder U-Bahnfahrten sind dagegen nicht automatisch reine öffentliche Güter. Bei einer U-Bahn sind Zugangskontrollen möglich und Plätze können knapp sein. Das Schwarzfahrer-Rollenspiel des ursprünglichen Arbeitsblatts beschreibt daher zwar ein Finanzierungsproblem, aber keinen eindeutigen Gegensatz zwischen Plan- und Marktwirtschaft.</p><h2>Kaufkraft, Sicherheit und Krisen</h2><p>Wer wenig Einkommen oder Vermögen hat, kann dringende Bedürfnisse möglicherweise nicht durch Käufe befriedigen. Ein geringes Einkommen beweist dabei keine geringe persönliche Leistung. Auch Herkunft, Eigentum, Verhandlungsmacht und andere Umstände können eine Rolle spielen. Darüber hinaus sind Abschwünge, Unternehmensverluste und Arbeitslosigkeit möglich.</p><p>Für den Vergleich kommt es auf die Mechanismen an: Marktentscheidungen werden über Preise koordiniert, Planentscheidungen über verbindliche Vorgaben. Beide Systeme müssen knappe Mittel einsetzen und mit unvollständigen Informationen umgehen. <strong>Weder ein Plan noch ein Markt garantiert für sich allein eine gute Versorgung aller Menschen.</strong></p><p class="reading-question"><strong>Denke beim Lesen mit:</strong> Kann eine Fahrradproduktion besonders effizient sein, obwohl sich manche Familien trotzdem kein Fahrrad leisten können?</p></div>`;
stations[4].reading=`<div class="reading-article"><p class="reading-lead">Ein guter Systemvergleich besteht nicht nur aus zwei Listen. Er erklärt, warum sich Entscheidungen, Anreize und mögliche Ergebnisse unterscheiden. Verwende dafür auf beiden Seiten dieselben Kriterien.</p><h2>Beginne mit der Koordination</h2><p>Die zentrale Frage lautet: <strong>Wie werden die Entscheidungen vieler Beteiligter aufeinander abgestimmt?</strong> In der Zentralverwaltungswirtschaft legt eine staatliche Planungsbehörde verbindliche Vorgaben fest. In der freien Marktwirtschaft entscheiden Unternehmen und Haushalte dezentral; ihre Entscheidungen werden über Märkte und Preise verbunden. Aus diesem Unterschied ergeben sich weitere Merkmale, etwa die Bedeutung des Eigentums an Produktionsmitteln und die Rolle des Staates.</p>${lessonFigure('vergleich')}<h2>Begründe Stärken und Probleme</h2><p>Verbinde eine Regel mit dem Verhalten, das sie begünstigen kann. Eine zentrale Stückzahlvorgabe kann zum Beispiel dazu führen, dass ein Betrieb viele kleine Schrauben herstellt. Wettbewerb kann ein Unternehmen dazu bewegen, ein haltbareres Fahrrad anzubieten. Damit erklärst du einen Zusammenhang, statt nur „Fehlanreize“ oder „Innovation“ aufzuschreiben.</p><p>Unterscheide außerdem Ziele von Ergebnissen. Eine Grundversorgung kann politisch angestrebt werden, ohne dass sie immer gelingt. Gewinnstreben kann eine effiziente Produktion begünstigen, ohne eine gerechte Verteilung zu garantieren. Begriffe wie „immer“, „vollständig“ oder „automatisch“ passen deshalb selten zu einer begründeten Bewertung.</p><h2>Modelle sind keine Länderporträts</h2><p>Die DDR kann als historisches Beispiel einer überwiegend zentral geplanten Wirtschaft dienen. Die USA sind ein Beispiel einer marktwirtschaftlich geprägten Wirtschaft mit staatlichen Regeln und Eingriffen. Beide Beispiele helfen beim Verständnis; sie dürfen nicht mit den reinen Modellen gleichgesetzt werden. Ebenso sind Marx, Engels und Smith wichtige Vordenker, keine alleinigen Erfinder aller späteren Wirtschaftsordnungen.</p><p>Nutze nun deine bisherigen Notizen und ergänze die Vergleichstabelle möglichst aus dem Gedächtnis. Bei Lohnbildung, Verträgen und der Rolle des Staates beschreibst du jeweils das Grundmodell. Prüfe deine eigenen Formulierungen anschließend anhand der Lösungsvorschläge.</p><details><summary>Optional zu zweit: zwei Entscheidungswege durchspielen</summary><p>Übernehmt erst die Rollen einer Planungsbehörde und eines Betriebs, danach die eines Unternehmens und eines Haushalts. In beiden Fällen werden mehr Fahrräder gebraucht. Besprecht: Wer entscheidet über mehr Produktion? Welche Informationen braucht diese Person oder Stelle? Welche Schwierigkeit kann entstehen?</p><p>Haltet danach jeweils allein euren Vergleich fest. Alle Pflichtaufgaben lassen sich auch ohne Partner bearbeiten.</p></details><p class="reading-question"><strong>Dein Maßstab:</strong> Kannst du zu jedem Unterschied erklären, welche Entscheidung dadurch anders zustande kommt?</p></div>`;
}
